package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.impl.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;

public class MapDeserializer_setIgnorableProperties_TriageGen0Test {

    private MapDeserializer deserializer;
    private JavaType mockMapType;
    private ValueInstantiator mockValueInstantiator;
    private KeyDeserializer mockKeyDeser;
    private JsonDeserializer<Object> mockValueDeser;
    private TypeDeserializer mockValueTypeDeser;

    @Before
    public void setUp() {
        mockMapType = Mockito.mock(JavaType.class);
        mockValueInstantiator = Mockito.mock(ValueInstantiator.class);
        mockKeyDeser = Mockito.mock(KeyDeserializer.class);
        mockValueDeser = Mockito.mock(JsonDeserializer.class);
        mockValueTypeDeser = Mockito.mock(TypeDeserializer.class);

        deserializer = new MapDeserializer(
                mockMapType,
                mockValueInstantiator,
                mockKeyDeser,
                mockValueDeser,
                mockValueTypeDeser
        );
    }

    /**
     * Helper method to access the private field _ignorableProperties via reflection
     * to verify the internal state of the deserializer.
     */
    @SuppressWarnings("unchecked")
    private Set<String> getIgnorableProperties() throws Exception {
        Field field = MapDeserializer.class.getDeclaredField("_ignorableProperties");
        field.setAccessible(true);
        return (Set<String>) field.get(deserializer);
    }

    @Test
    public void testSetIgnorableProperties_NullInput() throws Exception {
        // When input is null, _ignorableProperties should be null
        deserializer.setIgnorableProperties(null);
        Assert.assertNull("Internal _ignorableProperties should be null when input is null", getIgnorableProperties());
    }

    @Test
    public void testSetIgnorableProperties_EmptyArray() throws Exception {
        // When input is empty array, _ignorableProperties should be null
        deserializer.setIgnorableProperties(new String[0]);
        Assert.assertNull("Internal _ignorableProperties should be null when input is empty", getIgnorableProperties());
    }

    @Test
    public void testSetIgnorableProperties_ValidArray() throws Exception {
        // When input is valid array, _ignorableProperties should contain the elements
        String[] ignorable = {"prop1", "prop2", "prop3"};
        deserializer.setIgnorableProperties(ignorable);

        Set<String> result = getIgnorableProperties();
        Assert.assertNotNull("Internal _ignorableProperties should not be null", result);
        Assert.assertEquals("Set size should match array length", 3, result.size());
        Assert.assertTrue(result.contains("prop1"));
        Assert.assertTrue(result.contains("prop2"));
        Assert.assertTrue(result.contains("prop3"));
    }

    @Test
    public void testSetIgnorableProperties_OverwriteExisting() throws Exception {
        // Verify that calling the method multiple times correctly overwrites the state
        String[] firstSet = {"a"};
        String[] secondSet = {"b", "c"};

        deserializer.setIgnorableProperties(firstSet);
        deserializer.setIgnorableProperties(secondSet);

        Set<String> result = getIgnorableProperties();
        Assert.assertEquals("Set size should reflect the last call", 2, result.size());
        Assert.assertTrue(result.contains("b"));
        Assert.assertFalse(result.contains("a"));
    }
}

/**
 * Mocking ValueInstantiator as it is part of Jackson internals and required for constructor.
 * Note: In a real environment, this would be provided by the Jackson library.
 */
abstract class ValueInstantiator {
    // Placeholder for compilation/mocking purposes
}
